(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[214],{350:(e,t,a)=>{"use strict";a.d(t,{W:()=>s});var i=a(5155),n=a(5016);function s(e){let{eyebrow:t,title:a,description:s,className:r,children:o}=e;return(0,i.jsx)("section",{className:(0,n.cn)("border-b border-grey-200 bg-white pb-14 pt-12 sm:pb-16 sm:pt-16 lg:pb-20 lg:pt-20",r),children:(0,i.jsx)("div",{className:"mx-auto max-w-7xl px-5 sm:px-7 lg:px-10",children:(0,i.jsxs)("div",{className:"max-w-3xl",children:[t?(0,i.jsxs)("p",{className:"mb-5 flex items-center gap-3 text-xs font-semibold uppercase tracking-[0.18em] text-grey-700",children:[(0,i.jsx)("span",{className:"inline-block h-1.5 w-1.5 rounded-full bg-purple","aria-hidden":"true"}),t]}):(0,i.jsx)("span",{className:"mb-5 block h-1.5 w-1.5 rounded-full bg-purple","aria-hidden":"true"}),(0,i.jsx)("h1",{className:"heading-display text-balance text-[2.25rem] text-black sm:text-5xl lg:text-[3.5rem]",children:a}),s?(0,i.jsx)("div",{className:"mt-6 max-w-2xl text-pretty text-base leading-relaxed text-grey-800 sm:text-lg",children:s}):null,o?(0,i.jsx)("div",{className:"mt-8",children:o}):null]})})})}},1027:(e,t,a)=>{Promise.resolve().then(a.bind(a,8175))},8175:(e,t,a)=>{"use strict";a.d(t,{InsightsContent:()=>d});var i=a(5155),n=a(2619),s=a.n(n),r=a(4367),o=a(350);let l=[{slug:"buying-property-spain-legal-checklist",title:"Buying property in Spain: a lawyer’s essential checklist",excerpt:"The documents, checks and sequencing that separate a secure acquisition from an avoidable risk. Written for serious international buyers.",category:"Legal guides",publishedAt:"2025-11-12",readMinutes:9,relatedPropertySlugs:["villa-sierra-blanca","penthouse-marina-banus"],content:["Acquiring property on the Costa del Sol is straightforward when the legal sequence is correct. It becomes expensive when it is not. This guide outlines the essential checks that should precede any reservation or private contract.","Title and charges. The first instruction is always a full Nota Simple from the Land Registry, followed by a deeper title review where necessary. You need clarity on ownership, mortgages, embargoes, easements and any pending legal proceedings. A clean fa\xe7ade is not evidence of clean title.","Planning and building status. For villas and plots especially, verify that what stands on the land is authorised. Request building licences, first occupation licences (licencia de primera ocupaci\xf3n or equivalent habitation certificate), and confirm there are no open urban planning files. On the Costa del Sol, irregular construction remains a material risk.","Community of owners. For apartments, townhouses and some gated villas, review community statutes, recent AGM minutes and the payment status of community fees. Outstanding debts can transfer with the property. So can restrictive rules that affect how you intend to use the home.","Tax position. Understand transfer tax (ITP) or VAT plus stamp duty (AJD), plus ongoing IBI, rubbish tax and wealth tax exposure where relevant. Non-residents have specific withholding and declaration obligations. Structure should be considered before, not after, completion.","The private contract. Never sign a reservation or arras agreement without legal review. Deposit terms, conditions precedent, completion timelines and penalty clauses must be precise. Ambiguity favours the party who drafted the document.","Completion and funds. Completion at the notary is the formal transfer. Funds must arrive through compliant banking channels. Power of attorney, NIE numbers and bank accounts should be arranged early for non-resident buyers. Last-minute administration is the most common source of delay.","At Yeselia & Co., legal review is not an add-on. It is the foundation of every acquisition we lead. If you are considering a purchase on the Costa del Sol, begin with clarity rather than urgency."]},{slug:"why-lawyer-led-agency-matters",title:"Why a lawyer-led agency changes the transaction",excerpt:"When legal expertise and property advisory sit in the same hands, the buyer’s risk profile changes. Here is how.",category:"Our approach",publishedAt:"2025-10-03",readMinutes:6,relatedPropertySlugs:["villa-benahavis"],content:["Most international buyers on the Costa del Sol assemble a team after they have fallen for a property: an agent, then a lawyer, then a tax adviser. By that point, emotional commitment often precedes legal certainty.","A lawyer-led practice reverses that sequence. Property selection, negotiation and legal due diligence are not separate commercial relationships. They are one coherent process under a single standard of care.","Alignment of incentives. A traditional agency is paid on completion. That is not inherently improper, but it can create pressure to proceed when caution is wiser. When the same professional is responsible for legal risk, the incentive is to complete only when the file is sound.","Earlier detection of issues. Planning irregularities, unresolved debts, incomplete licences and title defects are often discovered late. A dual-qualified adviser screens for them before serious negotiation begins, saving both time and deposit risk.","Clearer communication. International clients frequently receive conflicting messages from agent and lawyer. One voice, one chronology, one set of documents reduces friction and misinterpretation.","Discretion. High-value transactions attract attention. A compact, professional team that does not market your interest across a wide network is a material advantage for private buyers and sellers.","This is the model on which Yeselia & Co. is built. Serious properties. Serious buyers. Complete legal certainty."]},{slug:"selling-with-discretion-costa-del-sol",title:"Selling with discretion on the Costa del Sol",excerpt:"Not every owner wants a public listing. How confidential marketing works when privacy is non-negotiable.",category:"Selling",publishedAt:"2025-09-18",readMinutes:5,relatedPropertySlugs:["villa-sierra-blanca","villa-benahavis"],content:["Some properties should never appear on open portals. Owners with security concerns, public profiles or simply a preference for quiet sales need a different approach.","Confidential marketing means controlled exposure. The property is presented only to pre-qualified buyers who have demonstrated capacity and genuine intent. Viewings are scheduled, accompanied and limited. Details that identify the address may be withheld until a serious stage is reached.","Preparation still matters. Discretion is not an excuse for incomplete documentation. Title, licences, community status and a realistic valuation should be in order before any introduction is made. A prepared file shortens the buyer’s diligence and protects the seller’s negotiating position.","Pricing under privacy. Off-market does not mean underpriced. It means the audience is smaller and better informed. Accurate valuation against recent comparable transactions remains essential.","At Yeselia & Co., seller mandates can be structured as fully confidential, limited circulation, or conventional open marketing. The choice is yours. The standard of care is the same."]},{slug:"non-resident-buyers-nie-banking",title:"Non-resident buyers: NIE, banking and completion logistics",excerpt:"The practical sequence for international purchasers: identification numbers, accounts, power of attorney and funds.",category:"Legal guides",publishedAt:"2025-08-07",readMinutes:7,relatedPropertySlugs:["villa-el-limonar","villa-estepona-coast"],content:["International buyers often underestimate the administrative path to completion in Spain. The legal purchase can be clear while the logistics still delay the notary appointment. Plan these items early.","NIE number. The N\xfamero de Identificaci\xf3n de Extranjero is required for the purchase, for tax, and usually for opening a Spanish bank account. It can be obtained in Spain or via a Spanish consulate abroad. Power of attorney can allow a lawyer to manage this on your behalf.","Spanish bank account. Most completions and ongoing property costs are handled through a Spanish account. Banks apply anti-money-laundering checks. Source-of-funds documentation should be prepared in advance: employment income, sale of previous assets, inheritance or corporate distributions, as applicable.","Power of attorney. If you cannot attend the notary in person, a power of attorney executed before a notary (and apostilled if signed outside Spain) allows your representative to sign. Drafting must be specific enough for the transaction yet flexible enough for minor last-minute adjustments.","Currency and transfers. Large international transfers require lead time. Banks may request additional information mid-process. Build buffer into your completion timetable.","Tax representatives. Non-residents typically need a fiscal representative in Spain for property-related tax filings. Arrange this as part of the post-completion package, not as an afterthought.","Yeselia & Co. coordinates these steps as part of a single acquisition process, so legal and administrative workstreams do not diverge."]},{slug:"golden-mile-vs-new-golden-mile",title:"Golden Mile and New Golden Mile: a precise comparison",excerpt:"Two of Marbella’s most referenced residential corridors, explained without marketing exaggeration.",category:"Locations",publishedAt:"2025-07-22",readMinutes:6,relatedPropertySlugs:["villa-sierra-blanca","villa-nagueles","villa-estepona-coast"],content:["The terms Golden Mile and New Golden Mile are used loosely in marketing. For serious buyers, the distinctions matter: micro-location drives both lifestyle and residual value.","The Golden Mile. Traditionally the coastal and hillside strip between Marbella town and Puerto Ban\xfas. It includes established areas such as Nag\xfceles, Cascade de Camoj\xe1n and Sierra Blanca above. Proximity to Marbella’s centre, mature landscaping and long-standing prestige define the zone. Supply of prime plots is limited.","The New Golden Mile. Generally refers to the coastal corridor west of San Pedro toward Estepona. Development is more recent. Many communities offer modern specification, gated security and sea views at a different price point from the classic Golden Mile. The character is residential and resort-oriented rather than historic.","Which is right depends on the brief. Buyers seeking established address prestige and walkability to Marbella often prefer the Golden Mile. Those prioritising newer stock, larger plots or a quieter coastal stretch may look further west.","Neither label replaces due diligence on the specific urbanisation, building status and community. Micro-location within each corridor varies widely.","We advise on both areas with equal rigour. The property must fit the client’s legal, lifestyle and investment criteria, not a brochure slogan."]},{slug:"pre-sale-legal-preparation",title:"Preparing a property for sale: the legal file owners should assemble",excerpt:"A complete seller pack accelerates qualified buyers and prevents renegotiation at the notary.",category:"Selling",publishedAt:"2025-06-14",readMinutes:5,content:["The strongest sales are prepared before marketing begins. A complete legal and technical file signals seriousness and reduces the opportunity for late price pressure.","Core documents. Title deed (escritura), recent Nota Simple, IBI receipts, community fee certificates, energy performance certificate, and where relevant first occupation or habitation licences. For plots and villas, building licences and plans.","Utility and debt clearance. Confirm there are no outstanding utility debts or community arrears. Buyers’ lawyers will check; unresolved items delay completion.","Occupancy and inventory. Clarify whether the property is sold furnished, part-furnished or empty. List items included in the price. Ambiguity here generates unnecessary friction.","Access and viewings. Decide early whether viewings are open, by appointment, or limited to pre-qualified parties. Provide keys or access instructions to your adviser only.","Yeselia & Co. prepares seller files as standard. When you instruct us, the legal foundation is built before the first serious buyer is introduced."]}];var c=a(5016);function d(){let{t:e}=(0,r.Y)(),t=[...l].sort((e,t)=>new Date(t.publishedAt).getTime()-new Date(e.publishedAt).getTime());return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(o.W,{eyebrow:e("insights.hero.eyebrow"),title:e("insights.hero.title"),description:e("insights.hero.desc")}),(0,i.jsx)("section",{className:"section-y bg-white pt-4 sm:pt-6",children:(0,i.jsx)("div",{className:"mx-auto max-w-7xl px-5 sm:px-7 lg:px-10",children:(0,i.jsx)("ul",{className:"divide-y divide-grey-200 border-y border-grey-200",children:t.map(t=>(0,i.jsx)("li",{children:(0,i.jsxs)(s(),{href:"/insights/".concat(t.slug,"/"),className:"group grid gap-4 py-8 transition-colors sm:grid-cols-12 sm:items-baseline sm:gap-8 sm:py-10",children:[(0,i.jsxs)("div",{className:"sm:col-span-3",children:[(0,i.jsx)("p",{className:"text-xs font-semibold uppercase tracking-[0.14em] text-grey-600",children:t.category}),(0,i.jsxs)("p",{className:"mt-2 text-sm text-grey-600",children:[(0,c.Y)(t.publishedAt)," \xb7 ",t.readMinutes," ",e("insights.minRead")]})]}),(0,i.jsxs)("div",{className:"sm:col-span-8",children:[(0,i.jsx)("h2",{className:"heading-section text-xl transition-colors group-hover:text-purple sm:text-2xl",children:t.title}),(0,i.jsx)("p",{className:"mt-3 max-w-2xl text-sm leading-relaxed text-grey-700 sm:text-base",children:t.excerpt})]}),(0,i.jsx)("div",{className:"hidden sm:col-span-1 sm:flex sm:justify-end",children:(0,i.jsx)("span",{className:"font-semibold text-grey-500 transition-colors group-hover:text-purple","aria-hidden":"true",children:"→"})})]})},t.slug))})})})]})}}},e=>{e.O(0,[619,334,441,255,120],()=>e(e.s=1027)),_N_E=e.O()}]);